class Counter { int value; int increment() { return ++value; } }

MethodHandle h = MethodHandles.lookup()
    .findVirtual(Counter.class, "increment", MethodType.methodType(int.class));
Counter c = new Counter();
int result = (int) h.invoke(c);
System.out.println(result);

class MathUtil { static int square(int n) { return n * n; } }

MethodHandle h = MethodHandles.lookup()
    .findStatic(MathUtil.class, "square", MethodType.methodType(int.class, int.class));
for (int i = 1; i <= 5; i++) {
    System.out.println((int) h.invoke(i));
}

class Point { int x, y; Point(int x, int y) { this.x = x; this.y = y; } }

MethodHandle ctor = MethodHandles.lookup()
    .findConstructor(Point.class, MethodType.methodType(void.class, int.class, int.class));
Point p = (Point) ctor.invoke(3, 4);

MethodHandle getX = MethodHandles.lookup().findGetter(Point.class, "x", int.class);
int x = (int) getX.invoke(p);
System.out.println(x);

MethodHandle setX = MethodHandles.lookup().findSetter(Point.class, "x", int.class);
setX.invoke(p, 99);
System.out.println(p.x); // 99

int direct = MathUtil.square(5);
int viaHandle = (int) h.invoke(5);
System.out.println(direct == viaHandle ? "PASS" : "FAIL");

try {
    int r = (int) h.invokeExact(5L); // typ long zamiast int - NIE zgadza sie z MethodType
} catch (WrongMethodTypeException e) {
    System.out.println(e.getMessage());
}
// invokeExact wymaga scislej zgodnosci typow w miejscu wywolania (polymorphic signature) -
// long != int, wiec rzuca wyjatek. invoke() dopuszcza automatyczne konwersje/zwezenia i
// mogloby zadzialac (lub tez rzucic wyjatek przy niebezpiecznym zwezeniu typu, zaleznie od kierunku).

class Vault { private String secret = "x"; }

Field field = Vault.class.getDeclaredField("secret");
field.setAccessible(true);
MethodHandles.Lookup lookup = MethodHandles.lookup();
MethodHandle getter = lookup.unreflectGetter(field);
MethodHandle setter = lookup.unreflectSetter(field);

Vault v = new Vault();
setter.invoke(v, "nowy sekret");
System.out.println(getter.invoke(v));

Method m = MathUtil.class.getDeclaredMethod("square", int.class);
MethodHandle h = MethodHandles.lookup().unreflect(m);
Object viaReflection = m.invoke(null, 6);
Object viaHandle = h.invoke(6);
System.out.println(viaReflection.equals(viaHandle) ? "PASS" : "FAIL");

long t1 = System.nanoTime();
for (int i = 0; i < 1_000_000; i++) method.invoke(target);
long reflectionMs = (System.nanoTime() - t1) / 1_000_000;

long t2 = System.nanoTime();
for (int i = 0; i < 1_000_000; i++) handle.invoke(target);
long handleMs = (System.nanoTime() - t2) / 1_000_000;

System.out.println("Reflection: " + reflectionMs + " ms, MethodHandle: " + handleMs + " ms");
// Po 'rozgrzaniu' JIT-em MethodHandle powinien byc zauwazalnie szybszy niz Method.invoke,
// zgodnie z teoria - JIT potrafi go lepiej zoptymalizowac/zinline'owac.

class Formatter {
    String format(int n) { return "int:" + n; }
    String format(String s) { return "String:" + s; }
}

MethodHandles.Lookup lookup = MethodHandles.lookup();
MethodHandle intFormat = lookup.findVirtual(Formatter.class, "format", MethodType.methodType(String.class, int.class));
MethodHandle strFormat = lookup.findVirtual(Formatter.class, "format", MethodType.methodType(String.class, String.class));
Formatter f = new Formatter();
System.out.println(intFormat.invoke(f, 5));
System.out.println(strFormat.invoke(f, "x"));

class Box {
    int size;
    Box() { size = 0; }
    Box(int size) { this.size = size; }
}

MethodHandles.Lookup lookup = MethodHandles.lookup();
MethodHandle ctor1 = lookup.findConstructor(Box.class, MethodType.methodType(void.class));
MethodHandle ctor2 = lookup.findConstructor(Box.class, MethodType.methodType(void.class, int.class));
Box b1 = (Box) ctor1.invoke();
Box b2 = (Box) ctor2.invoke(10);

MethodHandle[] ops = new MethodHandle[3];
MethodType t = MethodType.methodType(int.class, int.class, int.class);
ops[0] = lookup.findVirtual(Calculator.class, "add", t);
ops[1] = lookup.findVirtual(Calculator.class, "subtract", t);
ops[2] = lookup.findVirtual(Calculator.class, "multiply", t);

static int calculate(MethodHandle[] ops, Calculator c, int op, int a, int b) throws Throwable {
    return (int) ops[op].invoke(c, a, b);
}

class Identified { final String id; Identified(String id) { this.id = id; } }

try {
    MethodHandle setter = MethodHandles.lookup().findSetter(Identified.class, "id", String.class);
} catch (IllegalAccessException e) {
    System.out.println(e.getMessage());
}
// Pole final jest ustawiane TYLKO RAZ, w konstruktorze - jezyk Javy gwarantuje jego
// niezmiennosc po inicjalizacji, wiec MethodHandles (respektujac semantyke jezyka) w ogole
// nie pozwalaja zbudowac do niego settera - to nie kwestia dostepu, tylko natury pola final.

try {
    MethodHandle h = MethodHandles.lookup()
        .findVirtual(MathUtil.class, "nieIstnieje", MethodType.methodType(int.class));
} catch (NoSuchMethodException e) {
    System.out.println("Nie znaleziono metody: " + e.getMessage());
}

class TextBox {
    StringBuilder sb = new StringBuilder();
    TextBox append(String s) { sb.append(s); return this; }
    String build() { return sb.toString(); }
}

MethodHandle appendH = lookup.findVirtual(TextBox.class, "append", MethodType.methodType(TextBox.class, String.class));
MethodHandle buildH = lookup.findVirtual(TextBox.class, "build", MethodType.methodType(String.class));

TextBox box = new TextBox();
TextBox afterFirst = (TextBox) appendH.invoke(box, "a");
TextBox afterSecond = (TextBox) appendH.invoke(afterFirst, "b");
String result = (String) buildH.invoke(afterSecond);
System.out.println(result.equals(new TextBox().append("a").append("b").build()) ? "PASS" : "FAIL");

handle.invoke(obj, 5); // OK - invoke() automatycznie rozszerza int -> double
try {
    handle.invokeExact(obj, 5); // BLAD - MethodType oczekuje 'double', nie 'int'
} catch (WrongMethodTypeException e) {
    System.out.println(e.getMessage());
}
// invoke() stosuje te same reguly konwersji co zwykle wywolanie metody w Javie (widening),
// invokeExact wymaga BAJT W BAJT zgodnego typu z MethodType uchwytu - nawet 'bezpieczne'
// rozszerzenie int->double NIE jest tu dopuszczalne bez jawnego rzutowania w kodzie wywolujacym.

static Object callNoArg(Object target, String methodName, Class<?> returnType) throws Throwable {
    MethodHandle h = MethodHandles.lookup()
        .findVirtual(target.getClass(), methodName, MethodType.methodType(returnType));
    return h.invoke(target);
}

System.out.println(callNoArg(new Counter(), "increment", int.class));
System.out.println(callNoArg(new Point(1,2), "toString", String.class));

Map<String, MethodHandle> ops = new HashMap<>();
MethodType t = MethodType.methodType(int.class, int.class, int.class);
ops.put("add", lookup.findStatic(Ops.class, "add", t));
ops.put("subtract", lookup.findStatic(Ops.class, "subtract", t));
// ...

static int execute(Map<String, MethodHandle> ops, String opName, int a, int b) throws Throwable {
    return (int) ops.get(opName).invoke(a, b);
}

class Multiplier { int factor; Multiplier(int f) { factor = f; } int multiplyBy(int n) { return factor * n; } }

MethodHandle raw = lookup.findVirtual(Multiplier.class, "multiplyBy", MethodType.methodType(int.class, int.class));
Multiplier m = new Multiplier(3);
System.out.println((int) raw.invoke(m, 5)); // wymaga instancji + n

MethodHandle bound = raw.bindTo(m);
System.out.println((int) bound.invoke(5)); // tylko n - instancja juz 'zaszyta'

MethodHandle squareInt = lookup.findStatic(MathUtil.class, "square", MethodType.methodType(int.class, int.class));
MethodHandle squareLong = squareInt.asType(MethodType.methodType(long.class, long.class));
long result = (long) squareLong.invokeExact(5L);
System.out.println(result); // 25

